window.CASES = [
{id:'KOR',name:'韩国',en:'Republic of Korea',start:1960,region:'东亚 · 朝鲜半岛',coordinates:'36° N / 128° E',intro:'战争之后，如何建立生产能力？',geo:'半岛南部，多山，天然资源有限；陆路通道被军事分界线阻断。',rounds:[
{title:'外汇不够，工业化从哪里开始？',lead:'战争结束七年。大多数人仍生活在乡村，工厂需要进口机器，而出口几乎换不回足够的外汇。',constraints:[['外汇瓶颈','进口设备依赖援助与有限的出口收入。'],['农村与教育','土地改革已经发生，基础教育正在扩展；低工资不等于熟练劳动力。'],['制度与安全','四月革命推翻李承晚政权，新政府尚不稳固；半岛停战而未和平。']],context:{'产业与贸易':'农业占增加值约三分之一，出口规模很小。进口资本品受外汇约束。','财政与外汇':'国内储蓄与税基薄弱，美国援助是重要外部资源。','教育与土地':'1949 年土地改革法及战后实施改变了土地占有结构，初等教育逐渐普及。','基础设施':'战争造成破坏，电力、道路和港口仍需修复。'},options:[['扶持劳动密集型出口','以纺织、服装等产品换取外汇，再进口设备。','海外市场与质量门槛；短期低工资压力。'],['保护国内幼稚工业','提高进口壁垒，以国内市场培育生产能力。','市场较小；受保护企业可能长期依赖补贴。'],['农业与基本公共服务优先','先改善农村生产率、教育和公共卫生。','工业岗位与出口扩张可能较慢。']],actual:'1961 年军事政变后，政府强化经济计划。1962 年启动第一个五年计划；1964 年贬值，并逐步用信贷、税收与出口目标支持出口企业。',events:[['1962','五年计划启动，国家协调投资与信贷。'],['1964–1965','汇率调整、出口激励与日韩关系正常化。'],['1970','出口扩张，但进口设备和外部资金仍然重要。']],causes:['土地改革、基础教育和大量农村劳动力，为劳动力转移提供条件。','出口激励与信贷分配有助于企业进入国际市场，也产生寻租和集中风险。','美国援助、安全支持与市场，以及日韩关系正常化带来的资金，扩大了政策空间。','冷战格局提供了外部支持；这一组合并非所有贫穷国家都能获得。','无法从增长本身分离教育、援助、出口政策各自的净贡献；威权统治不是被此案例证明的必要条件。'],question:'如果出口企业永远拿到廉价信贷，你用什么可观察的条件决定停止支持？',cost:'增长伴随劳动权利受限、低工资与权力集中。收入增长不能抵消这些代价。'},
{title:'要不要跨进重化工业？',lead:'轻工业出口已经扩大。接下来是继续发挥现有优势，还是把稀缺资本投入钢铁、造船和机械？',constraints:[['资本密集','重工业投资规模大、回收慢，需要进口技术与设备。'],['出口基础','企业已积累生产与出口经验，但技术能力仍不均衡。'],['安全压力','半岛军事风险持续，政府对国防工业自主性的重视上升。']],context:{'产业与贸易':'轻工业出口积累外汇，钢铁和机械等中间品仍需大量进口。','财政与外汇':'国家控制的信贷体系能集中资金，但外债和担保增加脆弱性。','政治制度':'朴正熙政府集中权力，企业与政府之间形成紧密关系。','基础设施':'京釜高速公路于 1970 年通车，工业园区和港口建设继续。'},options:[['集中信贷发展重工业','扶持钢铁、机械、造船等规模产业。','债务、产能错配和企业集中风险。'],['继续深化轻工业出口','改善质量、物流和技能，积累资本后再升级。','可能错过产业配套与技术积累的窗口。'],['分散投资改善公共服务','优先提高教育、住房和农村生活条件。','短期产业升级速度可能放缓。']],actual:'1973 年政府推动重化工业化，向重点产业配置优惠信贷。大型企业集团扩张，工业能力增强，同时出现过度投资、债务和资源配置问题。',events:[['1973','重化工业化政策全面推进。'],['1973–1979','两次石油冲击推高进口能源成本。'],['1979–1980','政治动荡与宏观调整叠加，1980 年经济收缩。']],causes:['既有出口能力与工业配套支持升级，能源进口依赖则扩大冲击。','定向信贷加速产能建设，但保护也可能让低效率项目延续。','全球需求、海外借款条件和石油价格改变了投资收益。','石油冲击和政治危机的时点，难由产业规划者精确预见。','成功存续的企业更容易被历史记住；需同时考察失败项目和融资成本。'],question:'你会用出口表现、生产率还是就业来考核重工业项目？何时退出？',cost:'工业扩张伴随金融压抑、企业集中和劳工权利限制；1980 年的收缩暴露了调整成本。'},
{title:'已有工业基础，怎样走向下一阶段？',lead:'经济刚经历收缩。工业能力已经积累，但通胀、负债与政治冲突让“继续加码”不再是简单答案。',constraints:[['宏观稳定','通胀与投资失衡需要处理，紧缩也会损害就业。'],['企业结构','大企业拥有规模与经验，中小企业融资和竞争空间受限。'],['社会诉求','城市劳动力扩大，对工资、劳动权利和政治参与的要求增加。']],context:{'产业与贸易':'制造业更复杂，但对进口能源和外部需求仍敏感。','财政与外汇':'外债与通胀压力要求更审慎的投资和融资。','教育与技能':'中高等教育与技术培训扩展，产业对技能需求增加。','政治制度':'1980 年新军政府掌权，民主化诉求与压制并存。'},options:[['稳定物价并提高竞争','调整过度投资，渐进开放进口与金融。','短期失业、企业倒闭与债务处置成本。'],['继续集中资源扶持产业','通过定向支持推动电子、汽车等升级。','政府判断错误与企业过度借贷风险。'],['工资与社会保障优先','提高家庭收入、公共服务和劳动保护。','需协调企业竞争力、物价与财政负担。']],actual:'1980 年代政府推进稳定化、产业调整和部分开放，企业持续技术升级。1987 年民主化转折与工人运动改变劳资关系；后半期增长还受益于有利的国际价格条件。',events:[['1980 年代初','稳定化与重化工业投资调整。'],['1986–1988','低油价、低国际利率及日元升值改善外部条件。'],['1987','民主化转折，劳动者议价能力提高。']],causes:['此前积累的制造能力、教育与基础设施使企业能响应市场变化。','稳定化、产业调整与技术投入共同作用，政策并非单一自由化路线。','油价、利率及汇率环境有利于出口和国际收支。','三项有利外部条件同时出现，不能简单归为国内政策的功劳。','如果没有外部顺风会增长多少，无法由这一条历史路径精确识别。'],question:'哪些增长来自能力积累，哪些来自外部顺风？你要看什么证据来区分？',cost:'增长和民主化并未自动消除大企业集中、劳动市场分化和金融风险。'}]},
{id:'ARG',name:'阿根廷',en:'Argentina',start:1970,region:'南美洲 · 南大西洋',coordinates:'34° S / 64° W',intro:'有资源与工业，为什么仍受约束？',geo:'拥有肥沃的潘帕斯平原与农牧业出口基础，国内区域差异大，远离主要工业市场。',rounds:[
{title:'工业需要外汇，外汇从哪里来？',lead:'这个国家已经高度城市化，也拥有工业体系。但工业扩张需要进口设备，外汇收入仍受农牧产品出口影响。',constraints:[['分配冲突','城市工资、企业利润与农业出口收入之间存在张力。'],['工业与外汇','受保护工业依赖进口中间品和资本品。'],['政治不稳定','军政府执政，社会冲突和政策连续性问题突出。']],context:{'产业与贸易':'进口替代工业化已有基础；农牧产品仍是重要出口来源。','财政与外汇':'通胀、财政压力与国际收支约束反复出现。','教育与人口':'较高城市化与教育基础使其不同于典型低收入农业经济。','基础设施':'铁路、港口和工业城市已形成，内陆与沿海发展不均。'},options:[['保护工业，同时要求出口绩效','保留过渡保护，逐步以出口与效率作为支持条件。','执行需要可信退出机制，利益集团可能阻挠。'],['开放贸易与金融','降低保护，让竞争和资本流入推动调整。','汇率升值和短期资金可能伤害可贸易产业。'],['先达成财政与收入协调','协调税收、支出、工资和物价安排。','政治协商困难，冻结价格可能掩盖失衡。']],actual:'政策在不同政府之间剧烈转换。1976 年政变后，军政府推进贸易和金融开放；1978 年采用预先公布的贬值安排，实际汇率升值与外债积累成为重要问题。',events:[['1973','民选政府回归并尝试收入协调。'],['1976–1977','军事政变后推进金融自由化。'],['1978–1980','汇率安排与资本流动改变工业竞争条件。']],causes:['出口结构与工业进口需求，使外汇供应容易成为扩张的瓶颈。','贸易、金融和汇率改革的组合与时序，比单独“开放”更重要。','国际银行贷款扩张提供了融资，也增加外部利率暴露。','有利的融资窗口可能暂时掩盖结构问题，持续时间无法保证。','不能把随后的一切归于某一项改革；政治暴力、宏观政策与国际条件同时变化。'],question:'资本流入在为生产能力融资，还是在支撑高估汇率？怎样辨别？',cost:'军事独裁时期存在严重的人权侵害。经济数据不能概括这一时期的社会后果。'},
{title:'资本流入能不能永远持续？',lead:'外债与金融脆弱性正在累积。你面临一个冲突：维护汇率承诺，还是尽快调整并承认损失？',constraints:[['货币错配','外币债务使贬值损害资产负债表。'],['外部融资','国际利率上升，滚动融资开始更昂贵。'],['可信度','通胀惯性与政策反复，使稳定承诺难以获得信任。']],context:{'产业与贸易':'实际汇率与贸易开放对部分制造业构成压力。','财政与外汇':'债务偿付需求上升，银行和公共部门风险相互传导。','政治制度':'军事统治持续，国内支持与合法性承压。','基础设施':'已有城市工业体系，但投资受到宏观不稳定影响。'},options:[['调整汇率并重组债务','承认融资约束，协调债务与银行处置。','进口涨价、债务损失和政治阻力。'],['维护汇率并收紧财政','试图恢复市场信任与融资。','衰退可能恶化税收、就业和债务负担。'],['价格工资协调加定向支持','用收入政策抑制惯性，同时保护就业。','若财政货币不配套，稳定可能短暂。']],actual:'1981 年汇率安排崩溃，1982 年地区债务危机爆发。1983 年恢复民主，1985 年奥斯特拉尔计划一度降低通胀，但财政与融资问题未被持久解决，1989 年发生恶性通胀。',events:[['1981–1982','汇率调整与债务危机，融资空间收缩。'],['1983–1985','恢复民主，推出奥斯特拉尔稳定计划。'],['1989','恶性通胀侵蚀工资、储蓄与政策信任。']],causes:['外币债务与脆弱税基使利率、汇率变化向财政传导。','稳定计划在短期有成效，但持久配套与政治协调不足。','美国紧缩与拉美债务危机改变全球贷款条件。','危机时点和传染程度不由单个政府控制。','政策失败并不证明稳定化不可能；不同反事实需明确融资和政治可行性。'],question:'如果稳定方案三个月有效、一年后失效，你先检查哪些约束？',cost:'通胀与衰退让实际工资和储蓄缩水，调整负担在群体之间极不均衡。'},
{title:'用固定汇率重建信任，代价是什么？',lead:'恶性通胀刚摧毁人们对货币的信任。强力名义锚可能迅速稳定预期，也会限制未来的调整工具。',constraints:[['货币信任','居民难以相信新的反通胀承诺。'],['调整能力','固定汇率意味着更多依赖工资、价格与财政调整。'],['国家融资','债务期限、币种与税收能力决定承诺能维持多久。']],context:{'产业与贸易':'生产率差异较大，贸易伙伴汇率变化影响竞争力。','财政与外汇':'公共债务、地方财政和外币融资是稳定方案的关键。','政治制度':'民选政府需要在稳定、就业与改革支持之间协调。','社会条件':'通胀创伤提高稳定的政治吸引力，但失业代价同样重要。'},options:[['硬汇率锚加财政约束','通过可兑换承诺抑制货币扩张与通胀预期。','外部冲击下无法灵活贬值，需要可信退出安排。'],['有管理浮动与财政改革','保留汇率缓冲，以制度改革重建信誉。','短期稳定可信度不足，可能再度资本外流。'],['渐进稳定并优先保护就业','通过收入协调与逐步改革缓和调整。','若通胀预期不降，成本可能更高。']],actual:'1991 年可兑换计划将比索与美元挂钩，通胀大幅下降，同时推进私有化与开放。1990 年代出现增长和衰退交替，1998 年起经济衰退；本轮停在 2000 年，不把后来事件混入判断。',events:[['1991','可兑换制度建立，通胀迅速下降。'],['1995','墨西哥危机传导，经济衰退。'],['1998–2000','外部冲击与竞争力压力下再次衰退。']],causes:['美元化与货币信任危机使硬锚具有吸引力，也制造退出困难。','汇率承诺稳定价格，但财政、银行与劳动市场制度需共同支撑。','美元走强、资本流动逆转和巴西贬值加重调整压力。','外部冲击的组合和时序难以预知，但暴露程度可以管理。','十年累计增长掩盖末期衰退；换一个观察终点，评价可能改变。'],question:'当一种政策解决了通胀，却积累了另一种风险，你会设定什么退出条件？',cost:'低通胀改善日常交易，但失业和衰退给许多家庭带来持续压力。'}]},
{id:'SGP',name:'新加坡',en:'Singapore',start:1965,region:'东南亚 · 马六甲海峡',coordinates:'1° N / 104° E',intro:'没有腹地，如何创造就业？',geo:'位于重要海运通道，拥有转口港；土地与自然资源稀缺，水与原料依赖外部。',rounds:[
{title:'国内市场太小，还能怎样工业化？',lead:'刚刚独立的城市国家失去共同市场预期。港口是现成优势，但新的就业岗位不能只靠转口贸易。',constraints:[['市场规模','国内人口少，规模化制造必须面向外部市场。'],['岗位与技能','需要吸收劳动力，并建立工业技术与管理能力。'],['安全与供应','水源、粮食、原料依赖外部；国防与外交空间有限。']],context:{'产业与贸易':'转口贸易与港口服务发达，裕廊工业区和经济发展局已开始建设。','财政与外汇':'需以有限公共资源支持住房、基础设施和工业投资。','政治制度':'人民行动党执政，政府组织和执行能力较强，政治竞争空间有限。','教育与基础设施':'多语言劳动力与港口优势并存，技能培训和公共住房仍需扩展。'},options:[['吸引外资，进入出口制造','用园区、物流与培训连接跨国企业。','依赖外部企业决策，技术溢出并不自动发生。'],['保护本土企业，替代进口','用关税和采购培育本地工业。','小市场限制规模，成本可能很高。'],['集中发展港口与商业服务','巩固转口、航运和区域贸易枢纽。','未必创造足够不同技能层次的岗位。']],actual:'政府积极吸引出口制造外资，扩建工业园区、住房与基础设施，并组织技能培训。国有及政府关联企业也参与关键行业，政策并非单纯放任市场。',events:[['1965','独立后重新寻找市场与安全保障。'],['1968','劳动制度调整，外资制造加速进入。'],['1971–1975','英军撤离与油价冲击考验就业和外部适应。']],causes:['港口区位、贸易网络与行政基础为出口制造提供起点。','投资促进、基础设施和技能政策降低了企业落地成本。','跨国企业扩张和全球电子产业分工创造了机会。','企业选址与全球需求时点影响成效；区位本身也不是可复制政策。','很难把增长只归功于税收优惠；港口、住房、治理与国际环境同时作用。'],question:'如果外资工厂没有带来技术转移，你会如何设计本地配套与培训？',cost:'土地征用、劳动关系管制与快速城市重构产生分配和自由方面的代价。'},
{title:'低成本优势会一直存在吗？',lead:'出口制造已形成规模。劳动力与土地的约束逐渐显现，下一步是继续扩大低成本生产，还是主动提高技术门槛？',constraints:[['要素稀缺','土地有限，继续靠大量廉价劳动扩张面临瓶颈。'],['技术升级','更复杂的制造与服务需要技能、设备和企业网络。'],['外部需求','贸易规模远超国内经济，对全球周期非常敏感。']],context:{'产业与贸易':'电子、石化与港口服务扩张，外资企业具有重要地位。','财政与外汇':'开放经济需维护国际信任，同时投入住房、基础设施与培训。','教育与技能':'技术教育需求增加，需要让培训匹配企业实际岗位。','政治制度':'政府可协调工资与投资，但集中决策也可能误判调整速度。'},options:[['工资引导与技能升级同步','提高技能投入，推动企业采用更高生产率技术。','工资先于生产率上升可能损害就业。'],['保持成本竞争力','温和工资与持续招商，稳住现有制造业岗位。','可能延迟技术升级并强化低技能路径。'],['优先发展金融与商务服务','向高附加值服务转移资源。','服务业未必吸收制造业中的全部劳动力。']],actual:'1979 年起推动经济重组，以工资政策促进产业升级，配合技能发展。高成本与全球需求疲弱等因素叠加，1985 年出现独立后的首次年度衰退。',events:[['1979','工资调整与技能发展基金推动升级。'],['1980 年代初','技术密集产业与服务扩张。'],['1985','衰退促使政府重新检视成本和结构。']],causes:['土地和劳动力约束使低成本路线难以无限延续。','工资引导可能刺激升级，但企业适应需要时间与能力。','电子需求和区域经济变化影响出口与投资。','全球周期与国内成本调整叠加的时点加剧冲击。','不能仅因 1985 年衰退否定升级，也不能把所有成本归于外部需求。'],question:'你怎样判断企业是在升级前暂时受压，还是已经失去竞争力？',cost:'结构转型让部分工人面临技能不匹配；平均收入可能掩盖就业调整的负担。'},
{title:'衰退之后，如何修正发展路线？',lead:'经济刚经历衰退。现在需要修复成本竞争力，同时避免把长期技能和创新投资一起削掉。',constraints:[['成本调整','企业成本需要下降，但削减收入会压低家庭消费。'],['产业韧性','外资制造和国际服务都受全球景气影响。'],['社会分配','高技能转型可能拉大不同劳动者之间的机会差距。']],context:{'产业与贸易':'制造业与现代服务业并存，国际竞争日趋激烈。','财政与外汇':'政策需要平衡成本、长期投资和储蓄安排。','教育与技能':'培训、技术能力与企业研发成为更重要的竞争条件。','基础设施':'港口、机场与公共住房体系提供支撑，但土地依然稀缺。'},options:[['调整成本并持续升级','缓和工资及用工成本，保留技能和基础设施投入。','短期家庭收入受损，升级收益分配未必均衡。'],['公共投资刺激需求','以基础设施与公共服务稳住就业。','开放经济中需求可能流向进口，项目需有效率。'],['扩大服务业和区域布局','发展高附加值服务，与邻国形成生产网络。','跨境经营引入新的外部与分配风险。']],actual:'政府根据 1986 年经济委员会建议调整成本，包括降低雇主公积金缴费，同时支持制造升级与现代服务业。其后增长恢复，1990 年代进一步推进区域化。',events:[['1986','调整用工成本与经济政策。'],['1980 年代后期','全球电子需求回升，国内增长恢复。'],['1990 年代','发展现代服务与区域生产网络。']],causes:['既有物流、技能和政府协调能力缩短了适应过程。','成本调整与长期能力建设并行，避免只依赖单一价格竞争。','全球需求恢复与区域生产网络扩展创造增量空间。','复苏时点部分受外部周期影响，不能全归于政策纠偏。','政策与景气同时改善，无法精确断言各自贡献；也不应忽略被平均值遮蔽的群体。'],question:'如果下次外需再度下降，哪些能力能迁移，哪些只是依赖同一市场？',cost:'降低雇主公积金缴费缓解企业成本，也影响家庭储蓄积累；转型收益并不均匀。'}]}
];
